/**
 * The types `save/lifetime/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LifetimeImportEntryFields, LifetimeSaveFieldRow, LifetimeSaveExtract, LifetimeBreakdownSaveExtract
 * depends    —
 * used by    src/save/lifetime/breakdown, src/save/lifetime/index, src/save/lifetime/read
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from read.ts

export interface LifetimeImportEntryFields {
  date: string
  gameStarted: string
  coinsEarned: string
  cashEarned: string
  stonesEarned: string
  keysEarned: string
  cellsEarned?: string
  rerollShardsEarned?: string
  recentCoinsPerHour?: string
  damageDealt: string
  enemiesDestroyed: string
  wavesCompleted: string
  upgradesBought: string
  workshopUpgrades: string
  workshopCoinsSpent: string
  researchCompleted: string
  labCoinsSpent: string
  freeUpgrades: string
  interestEarned: string
  orbKills: string
  deathRayKills: string
  thornDamage: string
  wavesSkipped: string
}

export interface LifetimeSaveFieldRow {
  targetKey: keyof LifetimeImportEntryFields
  saveKey: string | readonly string[]
  /**
   * Spellings this field used to have, tried in order and only when `saveKey` is absent.
   *
   * NOT the same as giving `saveKey` an array: that form SUMS its keys, which is right for a
   * value split across three fields and wrong for a rename, where matching two spellings at once
   * would silently double the number.
   */
  renamedFrom?: readonly string[]
  label: string
  optional?: boolean
}

export interface LifetimeSaveExtract {
  values: Record<string, string>
  warnings: string[]
}

// from breakdown.ts

/** Lifetime totals the in-game Lifetime panel does not list, split by source. */
export interface LifetimeBreakdownSaveExtract {
  /** Kills by what killed them. */
  killsBySource: Record<string, number | null>
  /** Kills by enemy type. */
  killsByEnemyType: Record<string, number | null>
  /** Damage dealt by source. */
  damageBySource: Record<string, number | null>
  /** Coins earned by source. */
  coinsBySource: Record<string, number | null>
  /** Currency earned, spent and bought over the account's life. */
  currencies: Record<string, { earned: number | null; spent: number | null; bought: number | null }>
  /** Everything else the save totals: stuns, catches, death defies, lifesteal, play time. */
  other: Record<string, number | null>
}
